#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// Layout: j is the inner (fast) dimension, i is outer:
	// this matches the C layout u[i][j] with j as the stride‑1 dimension.
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);

	// Tunable micro‑optimization:
	// If true, we compute 1/denom once and replace two divisions
	// with multiplications in the tridiagonal solves.
	static constexpr bool use_reciprocal = true;
} tuning;


// initialization function
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	traverser(U).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const std::size_t n = U | get_length<'i'>();

	// Scalars as in the Polybench reference; keep the same variables so that
	// the SCOP region stays recognizable to polyhedral tools.
	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

	// Frequently used literals to avoid recomputing SCALAR_VAL(·)
	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

	// Build a base traverser once. It only stores structural information,
	// not indices, so reusing it across time steps is cheap.
	auto base_trav = traverser(U, V, P, Q);

	// Interior slices in i and j; re‑used for both sweeps.
	const auto interior_i = slice<'i'>(1, n - 2); // i = 1 .. n-2
	const auto interior_j = slice<'j'>(1, n - 2); // j = 1 .. n-2

#pragma scop

	DX = one / (num_t)n;
	DY = one / (num_t)n;
	DT = one / (num_t)tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = one + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = one + mul2;
	f = d;

	for (std::size_t t = 1; t <= tsteps; t++) {
		// ------------------------------------------------------------------
		// Column sweep: for each column i we solve a tridiagonal system
		// along j. We keep j as the inner (fast) dimension, which matches
		// the row‑major layout and yields good locality for P/Q/V.
		// ------------------------------------------------------------------
		base_trav
			.order(interior_i)
			.template for_dims<'i'>([&](auto trav_i) {
				const std::size_t i = get_index<'i'>(trav_i.state());

				// Boundary conditions for column i
				V[noarr::idx<'i', 'j'>(0,     i)] = one;
				P[noarr::idx<'i', 'j'>(i,     0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i,     0)] = V[noarr::idx<'i', 'j'>(0, i)];

				// Traverser over the interior in j for this fixed i
				auto trav_ij = trav_i.order(interior_j);

				// Forward sweep in j: j = 1 .. n-2
				trav_ij.for_each([&](auto state) {
					const auto prev_state = state - noarr::idx<'j'>(1);
					const std::size_t j = get_index<'j'>(state);

					const num_t denom = a * P[prev_state] + b;

					// Shared denominator: we can either divide twice (baseline)
					// or compute one reciprocal and multiply (tunable).
					if constexpr (tuning::use_reciprocal) {
						const num_t inv_denom = one / denom;
						P[state] = -c * inv_denom;

						const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j,     i - 1)];
						const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j,     i    )];
						const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j,     i + 1)];

						const num_t numer =
							(-d * u_j_im1) +
							((one + two * d) * u_j_i) -
							(f * u_j_ip1) -
							(a * Q[prev_state]);

						Q[state] = numer * inv_denom;
					} else {
						P[state] = -c / denom;

						const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j,     i - 1)];
						const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j,     i    )];
						const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j,     i + 1)];

						Q[state] =
							(-d * u_j_im1 +
							 (one + two * d) * u_j_i -
							 f * u_j_ip1 -
							 a * Q[prev_state]) / denom;
					}
				});

				// Boundary at bottom row
				V[noarr::idx<'i', 'j'>(n - 1, i)] = one;

				// Backward sweep in j: j = n-2 .. 1
				// Implemented as a forward sweep over k = 1 .. n-2
				// with j = n-1-k, to keep the traversal in the same
				// (cache‑friendly) order while honouring the dependency.
				trav_ij.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // j = n-2, n-3, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i,     j);
					const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

					V[noarr::idx<'i', 'j'>(j, i)] =
						P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
			});

		// ------------------------------------------------------------------
		// Row sweep: for each row i we solve a tridiagonal system along j,
		// this time updating U using V. The traversal pattern mirrors
		// the column sweep, so we retain the same data‑locality properties.
		// ------------------------------------------------------------------
		base_trav
			.order(interior_i)
			.template for_dims<'i'>([&](auto trav_i) {
				const std::size_t i = get_index<'i'>(trav_i.state());

				// Boundary conditions for row i
				U[noarr::idx<'i', 'j'>(i, 0)] = one;
				P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

				// Traverser over the interior in j for this fixed i
				auto trav_ij = trav_i.order(interior_j);

				// Forward sweep in j: j = 1 .. n-2
				trav_ij.for_each([&](auto state) {
					const auto prev_state = state - noarr::idx<'j'>(1);
					const std::size_t j = get_index<'j'>(state);

					const num_t denom = d * P[prev_state] + e;

					if constexpr (tuning::use_reciprocal) {
						const num_t inv_denom = one / denom;
						P[state] = -f * inv_denom;

						const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
						const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
						const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

						const num_t numer =
							(-a * v_im1_j) +
							((one + two * a) * v_i_j) -
							(c * v_ip1_j) -
							(d * Q[prev_state]);

						Q[state] = numer * inv_denom;
					} else {
						P[state] = -f / denom;

						const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
						const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
						const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

						Q[state] =
							(-a * v_im1_j +
							 (one + two * a) * v_i_j -
							 c * v_ip1_j -
							 d * Q[prev_state]) / denom;
					}
				});

				// Boundary at rightmost column
				U[noarr::idx<'i', 'j'>(i, n - 1)] = one;

				// Backward sweep in j: j = n-2 .. 1
				trav_ij.for_each([&](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // j = n-2, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
			});
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
