	const num_t center_coef_col = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d; // used in column sweep
	const num_t center_coef_row = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a; // used in row sweep

