	// These are used in both column and row sweeps.
	auto interior_i = noarr::slice<'i'>(1, n - 2);
	auto interior_j = noarr::slice<'j'>(1, n - 2);

	// Traverser restricted to the interior in 'i'.
	// Reused across all time steps and both sweeps.
	auto trav_interior_i = noarr::traverser(U, V, P, Q).order(interior_i);

	for (std::size_t t = 1; t <= tsteps; t++) {
		// ------------------------------------------------------------------
		// Column sweep: solve tridiagonal systems along the j-direction
		// for each interior column index i independently.
		// ------------------------------------------------------------------
		trav_interior_i.template for_dims<'i'>([&](auto trav_i) {
			const auto state_i = trav_i.state();
			const std::size_t i = get_index<'i'>(state_i);

			// Boundary conditions for column i
			V[noarr::idx<'i', 'j'>(0,     i)] = SCALAR_VAL(1.0);
			P[noarr::idx<'i', 'j'>(i,     0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i,     0)] = V[noarr::idx<'i', 'j'>(0, i)];

