//   scalar<num_t>() ^ (j_vec ^ i_vec) ^ set_length<'i','j'>
//
// This yields a 2D structure with dimensions 'i' and 'j' where 'j' is the
// innermost (fastest-varying) dimension. In C terms this corresponds to
// u[i][j] stored in row-major order (contiguous in j).
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

