	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
// -----------------------
// Traverses the whole 2D domain in a cache-friendly order (i outer, j inner),
// matching the underlying row-major layout (contiguous in 'j').
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	traverser(U).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
// ------------------
// Alternating Direction Implicit (ADI) solver.
// The core structure follows the original PolyBench kernel:
//
//   for t in 1..tsteps:
//     column sweep  (implicit in "vertical" direction, along j)
//     row sweep     (implicit in "horizontal" direction, along j)
//
// Dependency structure along 'j' inside each line is strictly sequential
// (tridiagonal forward/backward sweep), so we focus on:
//
//   * unit-stride access along 'j' (the innermost dimension),
//   * minimizing traverser construction overhead by reusing
//     pre-built proto-structures and inner traversers,
//   * hoisting loop-invariant scalar expressions out of the sweeps.
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const auto n = U | get_length<'i'>();

	// Scalar coefficients (kept as in the original code for PolyBench's SCoP)
	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

#pragma scop

	// Time/space steps and scheme coefficients (loop-invariant)
	DX = SCALAR_VAL(1.0) / (num_t)n;
	DY = SCALAR_VAL(1.0) / (num_t)n;
	DT = SCALAR_VAL(1.0) / (num_t)tsteps;

	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);

	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = SCALAR_VAL(1.0) + mul1;
	c = a;

	d = -mul2 / SCALAR_VAL(2.0);
	e = SCALAR_VAL(1.0) + mul2;
	f = d;

	// Additional precomputed constants used inside the sweeps.
	// These are hoisted out of the innermost loops to avoid recomputing
	// simple expressions like (1 + 2*d) at every grid point.
	const num_t diag_col = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d; // column sweep
	const num_t diag_row = SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a; // row sweep

	// Proto-structures describing the interior domain (1 .. n-2) in both
	// dimensions. These are reused across all time-steps to avoid recreating
	// equivalent slice objects over and over.
	const auto sweep_i = noarr::slice<'i'>(1, n - 2);
	const auto sweep_j = noarr::slice<'j'>(1, n - 2);

	for (std::size_t t = 1; t <= tsteps; t++) {

		// -----------------------------------------------------------------
		// Column sweep: for each interior column index i, solve a 1D
		// tridiagonal system along j.
		//
		// Memory layout is [i][j] with 'j' innermost, so for each fixed i
		// we traverse j in unit stride, which is cache- and prefetch-friendly.
		// -----------------------------------------------------------------
		auto trav_cols = traverser(U, V, P, Q).order(sweep_i);

		trav_cols.template for_dims<'i'>([&](auto trav_i) {
			const auto i = get_index<'i'>(trav_i.state());

			// Boundary conditions for column i:
			//   V[0][i] = 1
			//   P[i][0] = 0
			//   Q[i][0] = V[0][i]
			const auto top_0_i = idx<'i', 'j'>(0, i);
			const auto pi0     = idx<'i', 'j'>(i, 0);

			V[top_0_i] = SCALAR_VAL(1.0);
			P[pi0]     = SCALAR_VAL(0.0);
			Q[pi0]     = V[top_0_i];

			// Reusable j-traverser covering j = 1 .. n-2 for this fixed i.
			auto trav_ij = trav_i.order(sweep_j);

			// ---- Forward sweep in j: j = 1 .. n-2 ----
			// This is a standard Thomas forward elimination on each column.
			trav_ij.for_each([&](auto state) {
				// 'state' holds ('i' fixed, 'j' current).
				const auto prev = state - idx<'j'>(1); // j-1

				const num_t denom = a * P[prev] + b;
				P[state] = -c / denom;

				const std::size_t j = get_index<'j'>(state);

				// Note: U is accessed as U[j][i +/- 1] here, i.e., we are
				// reading three neighboring columns at the same row 'j'.
				// Indexing is intentionally written with explicit idx<>'s
				// to mirror the original C reference code.
				const num_t u_j_im1 = U[idx<'i', 'j'>(j, i - 1)];
				const num_t u_j_i   = U[idx<'i', 'j'>(j, i)];
				const num_t u_j_ip1 = U[idx<'i', 'j'>(j, i + 1)];

				Q[state] = (-d * u_j_im1
				            + diag_col * u_j_i
				            - f * u_j_ip1
				            - a * Q[prev]) / denom;
			});

			// Bottom boundary of column i:
			//   V[n-1][i] = 1
			V[idx<'i', 'j'>(n - 1, i)] = SCALAR_VAL(1.0);

			// ---- Backward sweep in j: j = n-2 .. 1 ----
			//
			// Traverser iterates j forward (1..n-2), so we introduce k
			// as the forward index and map it to a descending j:
			//     j = n - 1 - k    => sequence n-2, n-3, ..., 1
			//
			// This keeps the traversal logic simple while preserving the
			// original recurrence order in j.
			trav_ij.for_each([&](auto state) {
				const std::size_t k = get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

				const auto pij_state   = idx<'i', 'j'>(i, j);
				const auto vjp1i_state = idx<'i', 'j'>(j + 1, i);

				V[idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		});

		// -----------------------------------------------------------------
		// Row sweep: for each interior row index i, solve a 1D tridiagonal
		// system along j, but now using V as input and updating U.
		// -----------------------------------------------------------------
		auto trav_rows = traverser(U, V, P, Q).order(sweep_i);

		trav_rows.template for_dims<'i'>([&](auto trav_i) {
			const auto i = get_index<'i'>(trav_i.state());

			// Boundary conditions for row i:
			//   U[i][0] = 1
			//   P[i][0] = 0
			//   Q[i][0] = U[i][0]
			const auto ui0_state = idx<'i', 'j'>(i, 0);

			U[ui0_state] = SCALAR_VAL(1.0);
			P[ui0_state] = SCALAR_VAL(0.0);
			Q[ui0_state] = U[ui0_state];

			// Reusable j-traverser for this row
			auto trav_ij = trav_i.order(sweep_j);

			// ---- Forward sweep in j: j = 1 .. n-2 ----
			trav_ij.for_each([&](auto state) {
				const auto prev = state - idx<'j'>(1); // j-1

				const num_t denom = d * P[prev] + e;
				P[state] = -f / denom;

				const std::size_t j = get_index<'j'>(state);

				// Now we read from V in the "vertical" direction: V[i +/- 1][j]
				const num_t v_im1_j = V[idx<'i', 'j'>(i - 1, j)];
				const num_t v_i_j   = V[idx<'i', 'j'>(i,     j)];
				const num_t v_ip1_j = V[idx<'i', 'j'>(i + 1, j)];

				Q[state] = (-a * v_im1_j
				            + diag_row * v_i_j
				            - c * v_ip1_j
				            - d * Q[prev]) / denom;
			});

			// Right boundary of row i:
			//   U[i][n-1] = 1
			U[idx<'i', 'j'>(i, n - 1)] = SCALAR_VAL(1.0);

			// ---- Backward sweep in j: j = n-2 .. 1 ----
			trav_ij.for_each([&](auto state) {
				const std::size_t k = get_index<'j'>(state);
				const std::size_t j = n - 1 - k; // n-2, ..., 1

				const auto pij_state   = idx<'i', 'j'>(i, j);
				const auto uijp1_state = idx<'i', 'j'>(i, j + 1);

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		});
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

