// Layout tuning
// -----------------------------------------------------------------------------

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// Layout: scalar -> j (inner) -> i (outer) to match C's u[i][j] row-major
	//   scalar<num_t> ^ (j_vec ^ i_vec)  ~  num_t u[N][N];
