	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// -----------------------------------------------------------------------------
// Initialization
// -----------------------------------------------------------------------------

// initialization function
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// U: i x j
	traverser(U).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// -----------------------------------------------------------------------------
// Computation kernel
// -----------------------------------------------------------------------------

// ADI kernel (optimized version)
//
// Main changes vs the baseline:
//  - Precompute frequently used scalar combinations (1 + 2*d, 1 + 2*a, etc.).
//  - Reuse "previous" P and Q values along the tridiagonal sweeps via
//    scalar temporaries (p_prev, q_prev) instead of reloading P[i][j-1]
//    and Q[i][j-1] from memory and doing state arithmetic.
//    This reduces memory traffic and state manipulation while preserving
//    exact numerical semantics: P[i][j-1] and Q[i][j-1] are only ever
//    used in the very next iteration along j.
//  - Factor out the interior slices in i and j once and reuse them.
//  - Keep all loop nests over i and j expressed via Noarr traversers
//    (for_dims / for_each), as required.
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// Core scalar coefficients
	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

#pragma scop

	// Discretization parameters
	DX = one / (num_t)n;
	DY = one / (num_t)n;
	DT = one / (num_t)tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	// Coefficients of the implicit scheme
	a = -mul1 / SCALAR_VAL(2.0);
	b = one + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = one + mul2;
	f = d;

	// Precompute constants used inside the inner sweeps
	num_t onePlus2d = one + two * d;
	num_t onePlus2a = one + two * a;

	// Interior domain [1, n-2] in each dimension
	const std::size_t interior_len = n - 2;
	const std::size_t last         = n - 1;

	auto interior_i = noarr::slice<'i'>(1, interior_len);
	auto interior_j = noarr::slice<'j'>(1, interior_len);

	for (std::size_t t = 1; t <= tsteps; t++) {

		// -----------------------------------------------------------------
		// Column sweep: for each column i, solve a tridiagonal system along j
		// -----------------------------------------------------------------
		auto trav_cols = traverser(U, V, P, Q).order(interior_i);

		trav_cols.template for_dims<'i'>([&](auto trav_i) {
			// trav_i has 'i' fixed, 'j' remaining
			auto i = get_index<'i'>(trav_i.state());

			// Boundary conditions for column i
			auto idx_v0i = noarr::idx<'i', 'j'>(0, i); // V[0][i]
			auto idx_pi0 = noarr::idx<'i', 'j'>(i, 0); // P[i][0] and Q[i][0]

			V[idx_v0i] = one;
			P[idx_pi0] = SCALAR_VAL(0.0);
			Q[idx_pi0] = V[idx_v0i];

			// Along this column, P and Q obey 1D recurrences in j:
			//   denom = a * P[i][j-1] + b
			//   P[i][j] = -c / denom
			//   Q[i][j] = ( ... - a * Q[i][j-1] ) / denom
			// Instead of indexing P[i][j-1]/Q[i][j-1] via state arithmetic
			// and extra loads, we keep them in scalars p_prev/q_prev.
			num_t p_prev = P[idx_pi0]; // = 0
			num_t q_prev = Q[idx_pi0]; // = V[0][i]

			// Forward sweep in j: j = 1..n-2
			auto trav_j = trav_i.order(interior_j);

			trav_j.for_each([&](auto state) {
				// state carries (i, j) where j in [1, n-2]
				auto j = get_index<'j'>(state);

				// Tridiagonal forward pass
				num_t denom = a * p_prev + b;
				num_t p_val = -c / denom;

				// 3-point vertical stencil on U along j for fixed column i
				num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j,     i - 1)];
				num_t u_j_i   = U[noarr::idx<'i', 'j'>(j,     i)];
				num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j,     i + 1)];

				num_t q_val =
					(-d * u_j_im1
					 + onePlus2d * u_j_i
					 - f * u_j_ip1
					 - a * q_prev) / denom;

				P[state] = p_val;
				Q[state] = q_val;

				// Update previous values for next j
				p_prev = p_val;
				q_prev = q_val;
			});

			// Boundary at bottom row: V[n-1][i] = 1
			V[noarr::idx<'i', 'j'>(last, i)] = one;

			// Backward sweep in j: j = n-2 .. 1
			// We still traverse j forward (1..n-2), but map each iteration
			// to a decreasing j = n-1-k. This keeps the loop structure
			// expressible via a Noarr traverser while implementing the
			// backward substitution order.
			trav_j.for_each([&](auto state) {
				auto k = get_index<'j'>(state);      // k = 1..n-2
				std::size_t j = last - k;           // j = n-2, ..., 1

				auto pij_state   = noarr::idx<'i', 'j'>(i,   j);     // P[i][j]
				auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);   // V[j+1][i]

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		});

		// -----------------------------------------------------------------
		// Row sweep: for each row i, solve a tridiagonal system along j
		// -----------------------------------------------------------------
		auto trav_rows = traverser(U, V, P, Q).order(interior_i);

		trav_rows.template for_dims<'i'>([&](auto trav_i) {
			auto i = get_index<'i'>(trav_i.state());

			// Boundary conditions for row i
			auto idx_ui0 = noarr::idx<'i', 'j'>(i, 0); // U[i][0], P[i][0], Q[i][0]

			U[idx_ui0] = one;
			P[idx_ui0] = SCALAR_VAL(0.0);
			Q[idx_ui0] = U[idx_ui0];

			num_t p_prev = P[idx_ui0]; // = 0
			num_t q_prev = Q[idx_ui0]; // = U[i][0]

			// Forward sweep in j: j = 1..n-2
			auto trav_j = trav_i.order(interior_j);

			trav_j.for_each([&](auto state) {
				auto j = get_index<'j'>(state);

				num_t denom = d * p_prev + e;
				num_t p_val = -f / denom;

				// 3-point vertical stencil on V along i for fixed j
				num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
				num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
				num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

				num_t q_val =
					(-a * v_im1_j
					 + onePlus2a * v_i_j
					 - c * v_ip1_j
					 - d * q_prev) / denom;

				P[state] = p_val;
				Q[state] = q_val;

				p_prev = p_val;
				q_prev = q_val;
			});

			// Boundary at rightmost column: U[i][n-1] = 1
			U[noarr::idx<'i', 'j'>(i, last)] = one;

			// Backward sweep in j: j = n-2 .. 1
			trav_j.for_each([&](auto state) {
				auto k = get_index<'j'>(state);      // k = 1..n-2
				std::size_t j = last - k;           // j = n-2, ..., 1

				auto pij_state   = noarr::idx<'i', 'j'>(i, j);       // P[i][j]
				auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);   // U[i][j+1]

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		});
	}

#pragma endscop
}

