		// ------------------------------------------------------------------
		base_trav
			.order(interior_i)            // restrict 'i' to 1 .. n-2
			.template for_dims<'i'>([=](auto trav_i) {
				const auto i_state = trav_i.state();
				const std::size_t i = get_index<'i'>(i_state);

				// Boundary conditions for column i:
				//   v[0][i] = 1;
				//   p[i][0] = 0;
				//   q[i][0] = v[0][i];
				const auto v0i_state  = noarr::idx<'i', 'j'>(0, i);
				const auto pi0_state  = noarr::idx<'i', 'j'>(i, 0);
				V[v0i_state] = SCALAR_VAL(1.0);
				P[pi0_state] = SCALAR_VAL(0.0);
				Q[pi0_state] = V[v0i_state];

				// Precompute traverser over interior j for this fixed i.
				// This avoids re-applying the same `slice<'j'>` proto twice.
				auto trav_ij = trav_i.order(interior_j);

				// Forward sweep in j: j = 1 .. n-2
				trav_ij.for_each([=](auto state) {
					// state = (i, j)
					auto prev = state - noarr::idx<'j'>(1); // (i, j-1)
					const std::size_t j = get_index<'j'>(state);

					const num_t denom = a * P[prev] + b;
					P[state] = -c / denom;

					// Access neighbours of U in the "vertical" direction.
					const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
					const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i)];
					const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

					Q[state] = (-d * u_j_im1
					            + (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d) * u_j_i
					            - f * u_j_ip1
					            - a * Q[prev]) / denom;
				});

				// Boundary at bottom row:
				//   v[n-1][i] = 1;
				V[noarr::idx<'i', 'j'>(n - 1, i)] = SCALAR_VAL(1.0);

				// Backward sweep in j: j = n-2 .. 1
				// Implemented as forward sweep over k = 1 .. n-2 with j = n-1-k
				trav_ij.for_each([=](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

					V[noarr::idx<'i', 'j'>(j, i)] =
						P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
			});

		// ------------------------------------------------------------------
		// Row sweep
		//
		// Similar structure, now solving 1D tridiagonal systems along rows.
		// Compared to the original version, we access v[i-1][j] and
		// v[i+1][j] using state arithmetic (neighbouring 'i' indices)
		// instead of re-constructing index states from scratch. This keeps
		// the semantics identical but reduces index construction overhead
		// in the innermost loop and tends to generate better code.
		// ------------------------------------------------------------------
		base_trav
			.order(interior_i)            // restrict 'i' to 1 .. n-2
			.template for_dims<'i'>([=](auto trav_i) {
				const auto i_state = trav_i.state();
				const std::size_t i = get_index<'i'>(i_state);

				// Boundary conditions for row i:
				//   u[i][0] = 1;
				//   p[i][0] = 0;
				//   q[i][0] = u[i][0];
				const auto ui0_state = noarr::idx<'i', 'j'>(i, 0);
				U[ui0_state] = SCALAR_VAL(1.0);
				P[ui0_state] = SCALAR_VAL(0.0);
				Q[ui0_state] = U[ui0_state];

				// Precompute traverser over interior j for this fixed i.
				auto trav_ij = trav_i.order(interior_j);

				// Forward sweep in j: j = 1 .. n-2
				trav_ij.for_each([=](auto state) {
					// state = (i, j)
					auto prev = state - noarr::idx<'j'>(1); // (i, j-1)

					const num_t denom = d * P[prev] + e;
					P[state] = -f / denom;

					// Neighbour accesses in V using state arithmetic on 'i':
					//   (i-1, j), (i, j), (i+1, j)
					auto north = state - noarr::idx<'i'>(1);
					auto south = state + noarr::idx<'i'>(1);

					const num_t v_im1_j = V[north];
					const num_t v_i_j   = V[state];
					const num_t v_ip1_j = V[south];

					Q[state] = (-a * v_im1_j
					            + (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a) * v_i_j
					            - c * v_ip1_j
					            - d * Q[prev]) / denom;
				});

				// Boundary at rightmost column:
				//   u[i][n-1] = 1;
				U[noarr::idx<'i', 'j'>(i, n - 1)] = SCALAR_VAL(1.0);

				// Backward sweep in j: j = n-2 .. 1
				trav_ij.for_each([=](auto state) {
					const std::size_t k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // n-2, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
			});
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
	auto P = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto Q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);

	// initialize data
	init_array(U.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, U.get_ref(), V.get_ref(), P.get_ref(), Q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, U.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
